//! Running an AIR entry point on the interpreter with generated inputs, before and after canonicalization, and
//! comparing the two runs.
//!
//! The arguments are bound from the entry point's record in the module's AIR metadata (`!air.kernel`,
//! `!air.vertex`, `!air.fragment`, ...): `air.texture` and `air.sampler` arguments are object handles, other pointer
//! arguments are buffers of generated bytes (read-only in the constant address space), and value arguments
//! (builtins such as `air.thread_position_in_grid`, stage inputs) get generated values. This reads only the record
//! kinds it needs straight from the metadata; the typed decoding of the records is the AIR semantic layer's
//! (package S2), which this harness will use once it exists.

#![allow(dead_code)]

use std::collections::HashSet;

use airwgsl::api::FunctionConstant;
use airwgsl::interp::compare::{bytes_refine, refines};
use airwgsl::interp::memory::{Byte, Layout, RegionKind};
use airwgsl::interp::{self, Error, Externals, Memory, Options, Outcome, Scalar, Val};
use airwgsl::ir::layout::DataLayout;
use airwgsl::ir::{GlobalId, Metadata, Module, Type, TypeId, Value};
use airwgsl::passes::{self, specialize, static_init};

/// A deterministic generator (SplitMix64).
pub struct Rng(pub u64);

impl Rng {
    pub fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9e37_79b9_7f4a_7c15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
        z ^ (z >> 31)
    }

    pub fn below(&mut self, n: u64) -> u64 {
        self.next() % n.max(1)
    }
}

/// What an argument is bound to.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ArgKind {
    /// A buffer of the given address space.
    Buffer(u32),
    /// An object handle (texture, sampler, acceleration structure...).
    Object,
    /// A value.
    Value,
}

/// The kind of each argument of function `f`, from its entry-point record (pointer arguments without a record are
/// buffers).
pub fn arg_kinds(m: &Module, f: usize) -> Vec<ArgKind> {
    let func = &m.functions[f];
    let mut kinds: Vec<ArgKind> = func
        .args
        .iter()
        .map(|a| match m.types.get(a.ty) {
            Type::Ptr(asp) => ArgKind::Buffer(*asp),
            _ => ArgKind::Value,
        })
        .collect();
    for nm in &m.named_metadata {
        if !passes::ENTRY_LISTS.contains(&nm.name.as_str()) {
            continue;
        }
        for &rec in &nm.ops {
            if passes::record_function(m, rec) != Some(f) {
                continue;
            }
            let Metadata::Tuple { ops, .. } = m.md(rec) else { continue };
            for list in ops.iter().skip(1).flatten() {
                let Metadata::Tuple { ops: args, .. } = m.md(*list) else { continue };
                for a in args.iter().flatten() {
                    let Metadata::Tuple { ops: fields, .. } = m.md(*a) else { continue };
                    let idx = match fields.first().copied().flatten().map(|x| m.md(x)) {
                        Some(Metadata::Value { value: Value::Const(c), .. }) => {
                            passes::util::const_int(m, Value::Const(*c)).map(|v| v as usize)
                        }
                        _ => None,
                    };
                    let strings: Vec<String> = fields
                        .iter()
                        .flatten()
                        .filter_map(|x| match m.md(*x) {
                            Metadata::String(s) => Some(String::from_utf8_lossy(s).into_owned()),
                            _ => None,
                        })
                        .collect();
                    let Some(i) = idx else { continue };
                    if i >= kinds.len() {
                        continue;
                    }
                    if strings.iter().any(|s| s == "air.texture" || s == "air.sampler")
                        && matches!(kinds[i], ArgKind::Buffer(_))
                    {
                        kinds[i] = ArgKind::Object;
                    }
                }
            }
        }
    }
    kinds
}

/// The `[[buffer(n)]]` index of each argument of function `f` that is a buffer (`air.buffer` with
/// `air.location_index` in its record).
pub fn buffer_indices(m: &Module, f: usize) -> Vec<Option<u64>> {
    let mut out = vec![None; m.functions[f].args.len()];
    for nm in &m.named_metadata {
        if !passes::ENTRY_LISTS.contains(&nm.name.as_str()) {
            continue;
        }
        for &rec in &nm.ops {
            if passes::record_function(m, rec) != Some(f) {
                continue;
            }
            let Metadata::Tuple { ops, .. } = m.md(rec) else { continue };
            for list in ops.iter().skip(1).flatten() {
                let Metadata::Tuple { ops: args, .. } = m.md(*list) else { continue };
                for a in args.iter().flatten() {
                    let Metadata::Tuple { ops: fields, .. } = m.md(*a) else { continue };
                    let int = |k: usize| match fields.get(k).copied().flatten().map(|x| m.md(x)) {
                        Some(Metadata::Value { value: Value::Const(c), .. }) => {
                            passes::util::const_int(m, Value::Const(*c))
                        }
                        _ => None,
                    };
                    let string = |k: usize| match fields.get(k).copied().flatten().map(|x| m.md(x)) {
                        Some(Metadata::String(s)) => Some(String::from_utf8_lossy(s).into_owned()),
                        _ => None,
                    };
                    let Some(idx) = int(0) else { continue };
                    let is_buffer = (0..fields.len()).any(|k| string(k).as_deref() == Some("air.buffer"));
                    let loc = (0..fields.len()).find(|&k| string(k).as_deref() == Some("air.location_index"));
                    if let (true, Some(k), true) = (is_buffer, loc, (idx as usize) < out.len()) {
                        out[idx as usize] = int(k + 1).map(|v| v as u64);
                    }
                }
            }
        }
    }
    out
}

/// For each argument of function `f` that carries `[[function_constant(p)]]`: the global holding its predicate
/// (`air.function_constant` in its record, followed by `!{ptr @pred, !"type", !"name"}`).
pub fn predicates(m: &Module, f: usize) -> Vec<Option<u32>> {
    let mut out = vec![None; m.functions[f].args.len()];
    for nm in &m.named_metadata {
        if !passes::ENTRY_LISTS.contains(&nm.name.as_str()) {
            continue;
        }
        for &rec in &nm.ops {
            if passes::record_function(m, rec) != Some(f) {
                continue;
            }
            let Metadata::Tuple { ops, .. } = m.md(rec) else { continue };
            for list in ops.iter().skip(1).flatten() {
                let Metadata::Tuple { ops: args, .. } = m.md(*list) else { continue };
                for a in args.iter().flatten() {
                    let Metadata::Tuple { ops: fields, .. } = m.md(*a) else { continue };
                    let idx = match fields.first().copied().flatten().map(|x| m.md(x)) {
                        Some(Metadata::Value { value: Value::Const(c), .. }) => {
                            passes::util::const_int(m, Value::Const(*c))
                        }
                        _ => None,
                    };
                    let Some(idx) = idx else { continue };
                    for k in 0..fields.len() {
                        let is_fc = matches!(fields[k].map(|x| m.md(x)), Some(Metadata::String(s)) if s.as_slice() == b"air.function_constant");
                        if !is_fc {
                            continue;
                        }
                        let Some(Some(t)) = fields.get(k + 1) else { continue };
                        let Metadata::Tuple { ops: p, .. } = m.md(*t) else { continue };
                        if let Some(Metadata::Value { value: Value::Global(GlobalId::Var(g)), .. }) =
                            p.first().copied().flatten().map(|x| m.md(x))
                            && (idx as usize) < out.len()
                        {
                            out[idx as usize] = Some(*g);
                        }
                    }
                }
            }
        }
    }
    out
}

/// The inputs of one run: buffer contents and argument values, generated once and used for both runs.
#[derive(Clone, Debug)]
pub struct Inputs {
    pub buffers: Vec<Option<Vec<u8>>>,
    pub values: Vec<Option<Val>>,
}

pub const BUFFER_BYTES: usize = 1 << 16;

/// How buffer bytes are generated: every 4-byte word a float in [-4, 4), a small integer in [0, 64), or random bytes.
/// Shader code reads typed data from bytes it cannot know; the first two give the values kernels usually expect
/// (no NaN or infinity for fast-math code, small indices), the third everything else.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Fill {
    Floats,
    SmallInts,
    Random,
}

pub fn fill_bytes(n: usize, fill: Fill, rng: &mut Rng) -> Vec<u8> {
    let mut b = vec![0u8; n];
    for w in b.chunks_mut(4) {
        let word: [u8; 4] = match fill {
            Fill::Floats => ((rng.below(8000) as f32 - 4000.0) / 1000.0).to_le_bytes(),
            Fill::SmallInts => (rng.below(64) as u32).to_le_bytes(),
            Fill::Random => (rng.next() as u32).to_le_bytes(),
        };
        let k = w.len();
        w.copy_from_slice(&word[..k]);
    }
    b
}

/// Generated inputs for function `f`.
pub fn inputs(m: &Module, f: usize, kinds: &[ArgKind], rng: &mut Rng, thread: u64) -> Inputs {
    inputs_with(m, f, kinds, rng, thread, Fill::Random)
}

pub fn inputs_with(m: &Module, f: usize, kinds: &[ArgKind], rng: &mut Rng, thread: u64, fill: Fill) -> Inputs {
    let func = &m.functions[f];
    let mut buffers = Vec::new();
    let mut values = Vec::new();
    for (k, kind) in kinds.iter().enumerate() {
        match kind {
            ArgKind::Buffer(_) => {
                buffers.push(Some(fill_bytes(BUFFER_BYTES, fill, rng)));
                values.push(None);
            }
            ArgKind::Object => {
                buffers.push(None);
                values.push(None);
            }
            ArgKind::Value => {
                buffers.push(None);
                values.push(Some(value_of(m, func.args[k].ty, rng, thread)));
            }
        }
    }
    Inputs { buffers, values }
}

/// A generated value of type `ty`: small integers (builtins index buffers with them), floats in [-4, 4).
pub fn value_of(m: &Module, ty: TypeId, rng: &mut Rng, thread: u64) -> Val {
    match m.types.get(ty) {
        Type::Vector { len, elem, .. } => {
            Val::V((0..*len).map(|_| value_of(m, *elem, rng, thread).scalar().unwrap()).collect())
        }
        Type::Array { len, elem } => Val::A((0..*len).map(|_| value_of(m, *elem, rng, thread)).collect()),
        Type::Struct { .. } | Type::LiteralStruct { .. } => {
            Val::A(m.types.struct_elems(ty).unwrap().iter().map(|&e| value_of(m, e, rng, thread)).collect())
        }
        Type::Int(1) => Val::S(Scalar::int((rng.next() & 1) as u128)),
        Type::Int(_) => Val::S(Scalar::int((thread + rng.below(4)) as u128)),
        Type::Half => Val::S(Scalar::int(half_bits(rng) as u128)),
        Type::Float => {
            let v = (rng.below(8000) as f32 - 4000.0) / 1000.0;
            Val::S(Scalar::int(v.to_bits() as u128))
        }
        _ => Val::S(Scalar::int(0)),
    }
}

fn half_bits(rng: &mut Rng) -> u64 {
    let v = (rng.below(8000) as f64 - 4000.0) / 1000.0;
    airwgsl::interp::float::HALF.from_f64(v)
}

/// Random values for a module's function constants (some left without a value).
pub fn constant_values(m: &Module, rng: &mut Rng) -> Vec<FunctionConstant> {
    let dl = DataLayout::parse(&m.datalayout).unwrap();
    let mut out = Vec::new();
    for r in specialize::records(m) {
        if rng.below(5) == 0 {
            continue;
        }
        let ty = m.globals[r.global as usize].value_type;
        let size = dl.store_size(&m.types, ty).unwrap_or(0) as usize;
        let elem = m.types.scalar(ty);
        let lanes = m.types.vector_len(ty).unwrap_or(1) as usize;
        let mut v = vec![0u8; size];
        let esize = size / lanes.max(1);
        for l in 0..lanes {
            let e = &mut v[l * esize..(l + 1) * esize];
            if r.type_name.starts_with("bool") {
                e[0] = (rng.next() & 1) as u8;
            } else if matches!(m.types.get(elem), Type::Float) {
                let f = (rng.below(8000) as f32 - 4000.0) / 1000.0;
                e.copy_from_slice(&f.to_le_bytes());
            } else if matches!(m.types.get(elem), Type::Half) {
                e.copy_from_slice(&(half_bits(rng) as u16).to_le_bytes());
            } else {
                for b in e.iter_mut() {
                    *b = rng.next() as u8;
                }
            }
        }
        out.push(FunctionConstant {
            index: r.index,
            name: None,
            data_type: specialize::data_type(&r.type_name).unwrap_or(0),
            value: v,
        });
    }
    out
}

/// A finished run: its outcome or error, and its memory.
pub struct Run {
    pub result: Result<Outcome, Error>,
    pub memory: Memory,
}

/// Runs function `f` of `m` with `inputs`: the module's constructors first (with function constant values
/// `constants` in their globals), then `f`, once per invocation in `threads`, on one memory.
pub fn run(
    m: &Module,
    f: usize,
    kinds: &[ArgKind],
    invocations: &[Inputs],
    constants: Option<&[FunctionConstant]>,
    externals: Externals,
) -> Run {
    let mut mem = Memory::new();
    let mut opts = Options { externals, step_limit: 20_000_000, ..Options::default() };
    // Buffers and objects, labelled by argument.
    let mut regions = Vec::new();
    for (k, kind) in kinds.iter().enumerate() {
        let r = match kind {
            ArgKind::Buffer(asp) => {
                let data = invocations[0].buffers[k].as_ref().unwrap();
                Some(mem.add_data(RegionKind::Buffer, *asp, data, *asp != 2, format!("buffer argument {}", k)))
            }
            ArgKind::Object => {
                Some(mem.add(RegionKind::Object, 1, Vec::new(), false, format!("object argument {}", k)))
            }
            ArgKind::Value => None,
        };
        regions.push(r);
    }
    {
        let consts = constants.unwrap_or(&[]);
        let mut defined = HashSet::new();
        let recs = specialize::records(m);
        let dl = DataLayout::parse(&m.datalayout).unwrap();
        for c in consts {
            let Some(r) = recs.iter().find(|r| r.index == c.index) else { continue };
            let g = r.global;
            let Ok(reg) = interp::global_region(m, g, &mut mem) else { continue };
            let ty = m.globals[g as usize].value_type;
            let size = Layout { dl: &dl, types: &m.types }.store_size(ty).unwrap_or(0) as usize;
            for (i, b) in c.value[..size].iter().enumerate() {
                mem.region_mut(reg).bytes[i] = Byte::data(*b);
            }
            defined.insert(m.globals[g as usize].common.name.clone());
        }
        if !recs.is_empty() || constants.is_some() {
            opts.defined_constants = Some(defined);
        }
        for ctor in static_init::constructors(m) {
            if let Err(e) = interp::run(m, ctor, &[], &mut mem, &opts) {
                return Run { result: Err(e), memory: mem };
            }
        }
    }
    // An argument whose function-constant predicate is false is absent from the specialized function: it has no
    // value, which the run models as a poison pointer.
    let preds = predicates(m, f);
    let dl = DataLayout::parse(&m.datalayout).unwrap();
    let mut absent = vec![false; kinds.len()];
    for (k, p) in preds.iter().enumerate() {
        let Some(g) = p else { continue };
        let Ok(r) = interp::global_region(m, *g, &mut mem) else { continue };
        let size =
            Layout { dl: &dl, types: &m.types }.store_size(m.globals[*g as usize].value_type).unwrap_or(0) as usize;
        absent[k] = !specialize::predicate_present(&mem.region(r).bytes[..size]);
    }
    let mut last = None;
    for inv in invocations {
        let mut args = Vec::new();
        for (k, kind) in kinds.iter().enumerate() {
            args.push(match kind {
                ArgKind::Value => inv.values[k].clone().unwrap(),
                _ if absent[k] => Val::S(Scalar::POISON),
                _ => Val::S(mem.pointer(regions[k].unwrap(), 0)),
            });
        }
        let r = interp::run(m, f, &args, &mut mem, &opts);
        let stop = r.is_err();
        last = Some(r);
        if stop {
            break;
        }
    }
    Run { result: last.unwrap(), memory: mem }
}

/// How a pair of runs compares.
#[derive(Debug)]
pub enum Verdict {
    /// The second refines the first.
    Refines,
    /// The first run had undefined behavior: any second run refines it.
    FirstUb(String),
    /// The first run could not be evaluated; nothing is shown.
    FirstUnsupported(String),
    /// The second does not refine the first.
    Differs(String),
}

/// Compares the canonical run (`b`) against the original run (`a`).
pub fn compare(a: &Run, b: &Run) -> Verdict {
    let oa = match &a.result {
        Ok(o) => o,
        Err(Error::Ub { reason, location }) => return Verdict::FirstUb(format!("{} ({})", reason, location)),
        Err(e) => return Verdict::FirstUnsupported(e.to_string()),
    };
    let ob = match &b.result {
        Ok(o) => o,
        Err(e) => return Verdict::Differs(format!("the canonical run stopped: {}", e)),
    };
    match (&oa.ret, &ob.ret) {
        (Some(x), Some(y)) => {
            if let Err(e) = refines(x, &a.memory, y, &b.memory) {
                return Verdict::Differs(format!("return {}", e));
            }
        }
        (None, None) => {}
        _ => return Verdict::Differs("one run returns a value, the other none".into()),
    }
    if oa.events.len() != ob.events.len() {
        return Verdict::Differs(format!("{} events against {}", oa.events.len(), ob.events.len()));
    }
    for (k, (x, y)) in oa.events.iter().zip(ob.events.iter()).enumerate() {
        if x.callee != y.callee || x.args.len() != y.args.len() {
            return Verdict::Differs(format!("event {}: {} against {}", k, x.callee, y.callee));
        }
        for (p, q) in x.args.iter().zip(y.args.iter()) {
            if let Err(e) = refines(p, &a.memory, q, &b.memory) {
                return Verdict::Differs(format!("event {} ({}) argument {}", k, x.callee, e));
            }
        }
    }
    // Buffers, and globals the program can write, by label.
    for (_, ra) in a.memory.regions() {
        let writable =
            matches!(ra.kind, RegionKind::Buffer) || (matches!(ra.kind, RegionKind::Global(_)) && ra.writable);
        if !writable {
            continue;
        }
        let Some((_, rb)) = b.memory.regions().find(|(_, r)| r.label == ra.label) else {
            if matches!(ra.kind, RegionKind::Global(_)) {
                continue;
            }
            return Verdict::Differs(format!("{} is missing from the canonical run", ra.label));
        };
        if let Some(i) = bytes_refine(&ra.bytes, &a.memory, &rb.bytes, &b.memory) {
            return Verdict::Differs(format!(
                "{} byte {}: {:?} against {:?}",
                ra.label,
                i,
                ra.bytes.get(i),
                rb.bytes.get(i)
            ));
        }
    }
    Verdict::Refines
}

/// The entry points of a module: (function index, name).
pub fn entry_points(m: &Module) -> Vec<(usize, String)> {
    let mut out = Vec::new();
    for nm in &m.named_metadata {
        if !passes::ENTRY_LISTS.contains(&nm.name.as_str()) {
            continue;
        }
        for &rec in &nm.ops {
            if let Some(f) = passes::record_function(m, rec)
                && !m.functions[f].is_declaration()
            {
                out.push((f, m.functions[f].common.name.clone()));
            }
        }
    }
    out
}

/// Whether value `v` names global `g`.
pub fn is_global(v: Value, g: GlobalId) -> bool {
    v == Value::Global(g)
}
